def _greedy_optimize(
    self,
    city_center: Tuple[int, int],
    district_types: List[DistrictType],
    valid_tiles: List[Tuple[int, int]],
    current_placements: Dict[Tuple[int, int], DistrictType],
    best_placements: Dict[str, Tuple[int, int]],
    best_bonuses: Dict[str, int],
    best_total: int
) -> Tuple[Dict[str, Tuple[int, int]], Dict[str, int], int]:
    """Greedy optimization - place one district at a time"""

    rules = get_placement_rules(self.tiles, city_center, self.population)
    calculator = get_adjacency_calculator(self.tiles)

    # Count current specialty districts
    specialty_count = sum(1 for d in current_placements.values()
                        if d not in PlacementRules.NON_SPECIALTY_DISTRICTS and d != DistrictType.CITY_CENTER)

    if specialty_count >= self.max_districts:
        # Calculate total adjacency
        total, per_district = calculator.calculate_total_adjacency(current_placements)
        if total > best_total:
            best_total = total
            best_placements.clear()
            best_bonuses.clear()
            for (x, y), dtype in current_placements.items():
                if dtype != DistrictType.CITY_CENTER:
                    best_placements[dtype.name] = [x, y]
                    key = f"{dtype.name}@({x},{y})"
                    if key in per_district:
                        best_bonuses[dtype.name] = per_district[key].total_bonus
                    else:
                        best_bonuses[dtype.name] = 0
        return best_placements, best_bonuses, best_total

    # Try placing each district type at each valid location
    best_move = None
    best_move_bonus = -1

    for district_type in district_types:
        # Skip if already placed
        if any(d == district_type for d in current_placements.values()):
            continue

        for tile_pos in valid_tiles:
            if tile_pos in current_placements:
                continue

            # Validate placement
            result = rules.validate_placement(district_type, tile_pos[0], tile_pos[1], current_placements)
            if not result.valid:
                continue

            # Calculate what adjacency this would give
