            if total > best_move_bonus:
                best_move_bonus = total
                best_move = (tile_pos, district_type)

    if best_move:
        current_placements[best_move[0]] = best_move[1]
        return self._greedy_optimize(
            city_center, district_types, valid_tiles,
            current_placements, best_placements, best_bonuses, best_total
        )

    # No more valid moves
    total, per_district = calculator.calculate_total_adjacency(current_placements)
    if total > best_total:
        best_total = total
        best_placements.clear()
        best_bonuses.clear()
        for (x, y), dtype in current_placements.items():
